<script lang="ts">
  let myLp = 8000;
  let opponentLp = 7200;
  let phase = 'MAIN PHASE 1';
  let turn = 8;
  let finished = false;
  function changeLp(amount: number, player: 'me' | 'opponent') { if (player === 'me') myLp = Math.max(0, myLp + amount); else opponentLp = Math.max(0, opponentLp + amount); }
  function endTurn() { turn += 1; phase = 'DRAW PHASE'; }
</script>
